func (descriptor Descriptor) Validate() error {
	_, err := descriptor.CanonicalBytes()
	return err
}

// CanonicalBytes returns the deterministic v1 JSON representation used in OCI
// instance metadata and retry binding.
func (descriptor Descriptor) CanonicalBytes() ([]byte, error) {
	if err := descriptor.validateFields(); err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(descriptor)
	if err != nil {
		return nil, fmt.Errorf("%w: encode canonical JSON: %v", ErrInvalidDescriptor, err)
	}
	if len(wire) == 0 || len(wire) > MaxDescriptorBytes {
		return nil, fmt.Errorf("%w: canonical JSON exceeds %d bytes", ErrInvalidDescriptor, MaxDescriptorBytes)
	}
	return wire, nil
}

// Digest returns the lowercase SHA-256 digest of CanonicalBytes.
func (descriptor Descriptor) Digest() (string, error) {
	wire, err := descriptor.CanonicalBytes()
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(wire)
	return hex.EncodeToString(digest[:]), nil
}

func (descriptor Descriptor) validateFields() error {
	if descriptor.IsStatic() {
		cell, err := naming.RegionCell(descriptor.Region).Name()
		number, ok := strings.CutPrefix(descriptor.Node, cell+"-"+naming.Member+"-")
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, cell+"-"+naming.Controller+"-")
		}
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, regionNode(descriptor.Region))
		}
		if pool, isPool := strings.CutPrefix(descriptor.Node, cell+"-pool-"); !ok && isPool {
			// The scheme allows no hyphen in a pool name.
			_, number, ok = strings.Cut(pool, "-")
		}
		if err != nil || !validCellRegion(descriptor.Cell, descriptor.Region) || !ok ||
			naming.Validate(descriptor.Node) != nil || strings.Contains(number, "-") ||
			descriptor != Static(descriptor.Cell, descriptor.Region, descriptor.Node) {
			return fmt.Errorf("%w: static host must name one database, controller, node or pool server of its cell and nothing else", ErrInvalidDescriptor)
		}
		return nil
	}
	if descriptor.SchemaVersion != SchemaVersion || !validCellRegion(descriptor.Cell, descriptor.Region) ||
		!descriptorToken.MatchString(descriptor.Node) || !descriptorToken.MatchString(descriptor.Owner) ||
		!validCreateKey(descriptor.CreateKey) || !descriptorImageID.MatchString(descriptor.ImageID) ||
		descriptor.FleetGeneration == 0 || descriptor.HostAttempt == 0 || descriptor.IntentGeneration == 0 ||
		!entityid.Valid(descriptor.DatabaseID) || !entityid.Valid(descriptor.PartitionID) ||
		!entityid.Valid(descriptor.SeatID) ||
		!descriptorDigest.MatchString(descriptor.IntentPayloadDigest) ||
		!descriptorDigest.MatchString(descriptor.CanonicalRosterDigest) ||
		!descriptorDigest.MatchString(descriptor.ManagedHostProfileDigest) ||
		!descriptorDigest.MatchString(descriptor.RuntimeManifestDigest) {
		return fmt.Errorf("%w: required identity, generation, image, or digest binding", ErrInvalidDescriptor)
	}
	return nil
}

func DefaultDeadlines() Deadlines {
	return Deadlines{
		Creating:         15 * time.Minute,
		Attaching:        10 * time.Minute,
		Formatting:       30 * time.Minute,
		Resizing:         30 * time.Minute,
		Detaching:        10 * time.Minute,
		Deleting:         30 * time.Minute,
		MaxAttachRetries: 2,
	}
}

const maxDeadline = 24 * time.Hour

// WithDefaults fills zero fields from DefaultDeadlines.
func (deadlines Deadlines) WithDefaults() Deadlines {
	defaults := DefaultDeadlines()
	fill := func(value *time.Duration, fallback time.Duration) {
		if *value == 0 {
			*value = fallback
		}
	}
	fill(&deadlines.Creating, defaults.Creating)
	fill(&deadlines.Attaching, defaults.Attaching)
	fill(&deadlines.Formatting, defaults.Formatting)
	fill(&deadlines.Resizing, defaults.Resizing)
	fill(&deadlines.Detaching, defaults.Detaching)
	fill(&deadlines.Deleting, defaults.Deleting)
	if deadlines.MaxAttachRetries == 0 {
		deadlines.MaxAttachRetries = defaults.MaxAttachRetries
	}
	return deadlines
}

// Validate rejects negative or unbounded deadlines.
func (deadlines Deadlines) Validate() error {
	for _, value := range []time.Duration{
		deadlines.Creating, deadlines.Attaching, deadlines.Formatting,
		deadlines.Resizing, deadlines.Detaching, deadlines.Deleting,
	} {
		if value < 0 || value > maxDeadline {
			return errors.New("retained volume lifecycle deadlines must be between zero and 24h")
		}
	}
	if deadlines.MaxAttachRetries > 10 {
		return errors.New("retained volume attach retries must not exceed 10")
	}
	return nil
}

// For returns the deadline of phase, or zero for non-transitional phases.
func (deadlines Deadlines) For(phase Phase) time.Duration {
	deadlines = deadlines.WithDefaults()
	switch phase {
	case Creating:
		return deadlines.Creating
	case Attaching:
		return deadlines.Attaching
	case Formatting:
		return deadlines.Formatting
	case Resizing:
		return deadlines.Resizing
	case Detaching:
		return deadlines.Detaching
	case Deleting:
		return deadlines.Deleting
	default:
		return 0
	}
}

// Expired reports whether a transitional state has outlived its deadline. A
// zero Since or a Since in the future is treated as expired so a corrupt or
// clock-skewed record cannot wait forever.
func (deadlines Deadlines) Expired(state State, now time.Time) bool {
	limit := deadlines.For(state.Phase)
	if limit == 0 {
		return false
	}
	if state.Since.IsZero() || state.Since.After(now.Add(time.Minute)) {
		return true
	}
	return now.Sub(state.Since) >= limit
}

// Check moves an expired transitional state to Stuck. It returns the state
// unchanged and false otherwise.
func Check(state State, now time.Time, deadlines Deadlines) (State, bool) {
	if !state.Phase.Transitional() || !deadlines.Expired(state, now) {
		return state, false
	}
	return State{
		Phase: Stuck, Since: now.UTC(), StuckFrom: state.Phase, Attempts: state.Attempts,
		Reason: fmt.Sprintf("%s exceeded %s", state.Phase, deadlines.For(state.Phase)),
	}, true
}

// Remediation is the next safe action for a stuck volume. Every remediation
// that moves data access requires its own fencing proof at execution time;
// this decision never authorizes an effect by itself.
type Remediation string

const (
	RemediationNone Remediation = ""
	// RemediationForceDetachRetry force-detaches the stalled attachment (no
	// writer has ever been granted a mount through it) and retries the attach
	// on the same host with a fresh idempotency key.
	RemediationForceDetachRetry Remediation = "force-detach-retry"
	// RemediationReplaceHost gives up on the host: the volume is reattached to
	// a replacement only after the old instance is proven terminated.
	RemediationReplaceHost Remediation = "replace-host"
	// RemediationForceDetach repeats a stalled detach with force semantics.
	RemediationForceDetach Remediation = "force-detach"
	// RemediationOperator holds for an exact-resource operator workflow.
	RemediationOperator Remediation = "operator"
)

// Remediate chooses the remediation for a stuck state.
func Remediate(state State, deadlines Deadlines) Remediation {
	if state.Phase != Stuck {
		return RemediationNone
	}
	deadlines = deadlines.WithDefaults()
	switch state.StuckFrom {
	case Attaching:
		if state.Attempts < deadlines.MaxAttachRetries {
			return RemediationForceDetachRetry
		}
		return RemediationReplaceHost
	case Detaching:
		return RemediationForceDetach
	default:
		// Create, format, resize and delete stalls touch durable data or an
		// unknown provider outcome; automation never guesses.
		return RemediationOperator
	}
}

func (phase Phase) Transitional() bool {
	switch phase {
	case Creating, Attaching, Formatting, Resizing, Detaching, Deleting:
		return true
	default:
		return false
	}
}

func recordVolumeResize(ctx context.Context, cell string, epoch uint64, intent Intent, before, after oci.RetainedVolume) {
	if after.SizeGB <= before.SizeGB {
		return
	}
	key := fmt.Sprintf("volume_resize:%s:%d", after.ID, after.SizeGB)
	if decisionlog.Correlated(key) != "" {
		return
	}
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Region:  cell,
		Actor:   decisionlog.Actor{Slice: "storage"},
		Kind:    decisionlog.KindVolumeResized,
		Subject: decisionlog.Subject{Kind: "volume", ID: after.ID, Name: intent.DatabaseID + "/" + intent.PartitionID},
		Summary: fmt.Sprintf("Grew volume %s from %d to %d GB", after.ID, before.SizeGB, after.SizeGB),
		Reason:  "The member's resource profile needs a larger retained volume than it was created with.",
		Rule:    "placement.auto_grow_volumes",
		Signals: []decisionlog.Signal{{Name: "size_gb", Value: float64(before.SizeGB), Unit: "GB", Comparison: ">=",
			Threshold: decisionlog.Threshold(float64(after.SizeGB)), Passed: decisionlog.Passed(false)}},
		Status: decisionlog.StatusSucceeded,
		Epoch:  epoch,
	})
	decisionlog.Correlate(key, id)
}

func SetDefault(recorder Recorder) (restore func()) {
	var holder *recorderHolder
	if recorder != nil {
		holder = &recorderHolder{recorder: recorder}
	}
	previous := defaultRecorder.Swap(holder)
	return func() { defaultRecorder.CompareAndSwap(holder, previous) }
}

// Default returns the installed recorder, or nil when records go to the log.
func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

// Record journals one decision with the process-wide recorder and returns
// its ID, so a caller can link later decisions to it with ParentID. It never
// blocks on the network and never fails; see the package documentation.
func Record(ctx context.Context, decision Decision) string {
	if recorder := Default(); recorder != nil {
		return recorder.Record(ctx, decision)
	}
	return LogRecorder{}.Record(ctx, decision)
}

// LogRecorder writes decisions to the default structured logger. It is the
// fallback before a Journal is installed, and the recorder of processes
// without a regional stream (one-shot CLI commands, hosts).
type LogRecorder struct {
	Logger *slog.Logger
}

// Record logs the decision and returns its ID.
func (recorder LogRecorder) Record(ctx context.Context, decision Decision) string {
	decision = decision.Normalize(time.Now())
	logger := recorder.Logger
	if logger == nil {
		logger = slog.Default()
	}
	attrs := []slog.Attr{slog.String(observability.ComponentKey, "decision"), slog.Bool(observability.EventKey, true),
		slog.String("decision_id", decision.ID),
		slog.String("kind", string(decision.Kind)), slog.String("actor", decision.Actor.Slice),
		slog.String("subject", decision.Subject.String()), slog.String("status", string(decision.Status))}
	if decision.Region != "" {
		attrs = append(attrs, slog.String("region", decision.Region))
	}
	if decision.Reason != "" {
		attrs = append(attrs, slog.String("reason", decision.Reason))
	}
	if decision.ParentID != "" {
		attrs = append(attrs, slog.String("parent_id", decision.ParentID))
	}
	logger.LogAttrs(ctx, slog.LevelInfo, decision.Summary, attrs...)
	return decision.ID
}

func Correlate(key, id string) {
	if key == "" || id == "" {
		return
	}
	correlations.Lock()
	defer correlations.Unlock()
	if _, exists := correlations.ids[key]; !exists {
		correlations.order = append(correlations.order, key)
	}
	correlations.ids[key] = id
	for len(correlations.order) > maxCorrelations {
		delete(correlations.ids, correlations.order[0])
		correlations.order = correlations.order[1:]
	}
}

// Correlated returns the decision ID remembered for key, or "".
func Correlated(key string) string {
	correlations.Lock()
	defer correlations.Unlock()
	return correlations.ids[key]
}

func NewID() string { return newIDAt(time.Now()) }

func newIDAt(at time.Time) string { return entityid.NewAt(at) }

// Normalize fills defaults and enforces bounds. It never fails: a record that
// is too large loses detail rather than being dropped.
func (decision Decision) Normalize(now time.Time) Decision {
	decision.Version = Version
	if decision.Time.IsZero() {
		decision.Time = now
	}
	decision.Time = decision.Time.UTC()
	if !entityid.Valid(decision.ID) {
		decision.ID = newIDAt(decision.Time)
	}
	if decision.Status == "" {
		decision.Status = StatusSucceeded
	}
	decision.Region = strings.ToLower(clip(decision.Region, 64))
	decision.Kind = Kind(clip(string(decision.Kind), 64))
	decision.Actor.Slice = clip(decision.Actor.Slice, 64)
	decision.Actor.Member = clip(decision.Actor.Member, maxIdentityBytes)
	decision.Subject.Kind = clip(decision.Subject.Kind, 64)
	decision.Subject.ID = clip(decision.Subject.ID, maxIdentityBytes)
	decision.Subject.Name = clip(decision.Subject.Name, maxIdentityBytes)
	decision.Summary = clip(decision.Summary, maxSummaryBytes)
	decision.Reason = clip(decision.Reason, maxSummaryBytes)
	decision.Rule = clip(decision.Rule, maxTextBytes)
	decision.Outcome = clip(decision.Outcome, maxTextBytes)
	decision.ParentID = clip(decision.ParentID, 64)
	if len(decision.Signals) > maxSignals {
		decision.Signals = decision.Signals[:maxSignals]
	}
	decision.Signals = slices.Clone(decision.Signals)
	for index := range decision.Signals {
		signal := &decision.Signals[index]
		signal.Name = clip(signal.Name, 128)
		signal.Text = clip(signal.Text, maxTextBytes)
		signal.Unit = clip(signal.Unit, 32)
		signal.Comparison = clip(signal.Comparison, 8)
	}
	if len(decision.Alternatives) > maxAlternatives {
		decision.Alternatives = decision.Alternatives[:maxAlternatives]
	}
	decision.Alternatives = slices.Clone(decision.Alternatives)
	for index := range decision.Alternatives {
		decision.Alternatives[index].Option = clip(decision.Alternatives[index].Option, maxTextBytes)
		decision.Alternatives[index].Reason = clip(decision.Alternatives[index].Reason, maxTextBytes)
	}
	if len(decision.Related) > maxRelated {
		decision.Related = decision.Related[:maxRelated]
	}
	decision.Related = slices.Clone(decision.Related)
	for index := range decision.Related {
		decision.Related[index] = clip(decision.Related[index], 64)
	}
	if len(decision.Attrs) > 0 {
		attrs := make(map[string]string, min(len(decision.Attrs), maxAttrs))
		for _, key := range slices.Sorted(maps.Keys(decision.Attrs)) {
			if len(attrs) == maxAttrs {
				break
			}
			attrs[clip(key, 64)] = clip(decision.Attrs[key], maxTextBytes)
		}
		decision.Attrs = attrs
	}
	return fit(decision)
}

// fit sheds optional evidence until the encoded record is within
// MaxRecordBytes, so the durable copy is never refused for its size: the
// per-field bounds alone allow more than that once JSON escaping is
// counted. Attributes go first, then alternatives, related IDs and signals
// (newest listed last, dropped first), then the free text is shortened.
func fit(decision Decision) Decision {
	size := func() int {
		data, err := json.Marshal(decision)
		if err != nil {
			return 0
		}
		return len(data)
	}
	for size() > MaxRecordBytes {
		switch {
		case len(decision.Attrs) > 0:
			keys := slices.Sorted(maps.Keys(decision.Attrs))
			delete(decision.Attrs, keys[len(keys)-1])
		case len(decision.Alternatives) > 0:
			decision.Alternatives = decision.Alternatives[:len(decision.Alternatives)-1]
		case len(decision.Related) > 0:
			decision.Related = decision.Related[:len(decision.Related)-1]
		case len(decision.Signals) > 0:
			decision.Signals = decision.Signals[:len(decision.Signals)-1]
		case len(decision.Outcome) > 0:
			decision.Outcome = ""
		case len(decision.Reason) > maxTextBytes/4:
			decision.Reason = clip(decision.Reason, len(decision.Reason)/2)
		case len(decision.Summary) > maxTextBytes/4:
			decision.Summary = clip(decision.Summary, len(decision.Summary)/2)
		default:
			return decision
		}
	}
	return decision
}

func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

